def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(row.count(v) for row in grid))
    # Foreground is the non-background, non-2 color.
    fg=next(v for row in grid for v in row if v not in (bg,2))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(1,w-1):
            if grid[r][c]==bg and grid[r][c-1]==fg and grid[r][c+1]==fg: out[r][c]=2
    for c in range(w):
        for r in range(1,h-1):
            if grid[r][c]==bg and grid[r-1][c]==fg and grid[r+1][c]==fg: out[r][c]=2
    return out

