def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter,deque
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg=next(v for row in grid for v in row if v!=bg)
    comp=[[-1]*w for _ in range(h)]; k=0
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=fg or comp[r][c]>=0: continue
            comp[r][c]=k; q=deque([(r,c)])
            while q:
                y,x=q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==fg and comp[yy][xx]<0:
                        comp[yy][xx]=k;q.append((yy,xx))
            k+=1
    out=[row[:] for row in grid]
    for r in range(h):
        cells=[c for c in range(w) if comp[r][c]>=0]
        for i,a in enumerate(cells):
            for b in cells[i+1:]:
                if comp[r][a]!=comp[r][b]:
                    for c in range(a+1,b):
                        if grid[r][c]==bg:out[r][c]=2
    for c in range(w):
        cells=[r for r in range(h) if comp[r][c]>=0]
        for i,a in enumerate(cells):
            for b in cells[i+1:]:
                if comp[a][c]!=comp[b][c]:
                    for r in range(a+1,b):
                        if grid[r][c]==bg:out[r][c]=2
    return out
